"""v0.4 strict quality gate. Local test artifacts must be generated by trusted harness."""
from __future__ import annotations
from pathlib import Path
from quality.evidence import verify_test_evidence


class QualityGate:
    def __init__(self, root):
        self.root=Path(root).resolve()

    def evaluate(self, project_id, task_result, test_artifacts):
        workspace=(self.root/'workspaces'/project_id).resolve()
        if not workspace.is_relative_to((self.root/'workspaces').resolve()):
            return {'approved':False,'reason':'Workspace inválido'}
        if not task_result.success:
            return {'approved':False,'reason':'Resultado del agente fallido'}
        if not test_artifacts:
            return {'approved':False,'reason':'No existen pruebas ejecutadas'}
        if not all(verify_test_evidence(workspace, ref) for ref in test_artifacts):
            return {'approved':False,'reason':'Evidencia ausente, modificada o fallida'}
        return {'approved':True,'reason':'Pruebas locales registradas correctamente'}
